def test_1d_back_compat_still_works():
    """1D arrays continue to behave exactly as before the 2D change.

    The recursion collapses to the original 1D semantics when there's
    only one dimension; this is a targeted check that the back-compat
    path is intact even with the now-recursive handle_array_complex.
    """
    # Use the existing 1D helper rather than the 2D mock so we exercise
    # the fallback path that reads array_info.bounds when array_dimensions
    # is absent.
    array = make_mock_twincatitem(
        name="Main.motors",
        data_type=make_mock_type("MY_STRING", is_string=True),
        pragma="pv: STATE\nexpand-names: A, B, C",
        array_info=(1, 3),
    )
    chains = list(pragmas.chains_from_symbol(array))
    pvnames = {c.pvname for c in chains}
    assert pvnames == {"STATE:A", "STATE:B", "STATE:C"}


def test_2d_array_per_dim_selector_subsets_both_dims():
    """``array: 1..2 | 1..3`` slices outer to 1..2 and inner to 1..3.

    State-mover devices use generic FBs whose state table is sized to
    MAX dimensions but each instance only uses a slice (e.g. 2 motors x
    3 states out of MAX x MAX). The ``|``-separated form lets the
    pragma express that slice.
    """
    array = _make_2d_mock(
        "Main.astPositionState",
        dims=[(1, 4), (1, 5)],
        pragma="pv: STATE\narray: 1..2 | 1..3",
    )
    chains = list(pragmas.chains_from_symbol(array))
    tcnames = sorted(c.tcname for c in chains)
    assert tcnames == [
        "Main.astPositionState[1][1]",
        "Main.astPositionState[1][2]",
        "Main.astPositionState[1][3]",
        "Main.astPositionState[2][1]",
        "Main.astPositionState[2][2]",
        "Main.astPositionState[2][3]",
    ]


def test_2d_array_per_dim_selector_outer_only_back_compat():
    """A bare ``array: 1..2`` (no ``|``) slices outer only; inner stays full."""
