def test_axis_link_explicit_list_basic():
    """Explicit list assigns each axis to its corresponding array element.

    This is the case where afbMotorsNC[1..4] references GVL_Axes.Axes[5..8]
    — the realistic shared-GVL layout where the implicit %d form would
    silently cross-wire every motor.
    """
    array = make_mock_twincatitem(
        name="Main.afbMotorsNC",
        data_type=make_mock_type("MY_STRING", is_string=True),
        pragma=(
            "pv: TST:MAL\n"
            "expand-names: MMS, CLZ, CLF, YAG\n"
            "axis-link: GVL_Axes.Axes[5], GVL_Axes.Axes[6], "
            "GVL_Axes.Axes[7], GVL_Axes.Axes[8]"
        ),
        array_info=(1, 4),
    )
    chains = list(pragmas.chains_from_symbol(array))
    pv_to_link = {c.pvname: _get_axis_link(c.last) for c in chains}
    assert pv_to_link == {
        "TST:MAL:MMS": "GVL_Axes.Axes[5]",
        "TST:MAL:CLZ": "GVL_Axes.Axes[6]",
        "TST:MAL:CLF": "GVL_Axes.Axes[7]",
        "TST:MAL:YAG": "GVL_Axes.Axes[8]",
    }


def test_axis_link_explicit_list_whitespace_tolerated():
    """Surrounding whitespace and inconsistent spacing don't matter."""
    array = make_mock_twincatitem(
        name="Main.motors",
        data_type=make_mock_type("MY_STRING", is_string=True),
        pragma="pv: P\naxis-link:  GVL.A[1]  ,GVL.A[2],   GVL.A[3]   ",
        array_info=(1, 3),
    )
    chains = list(pragmas.chains_from_symbol(array))
    links = [_get_axis_link(c.last) for c in chains]
    assert links == ["GVL.A[1]", "GVL.A[2]", "GVL.A[3]"]


def test_axis_link_explicit_list_non_unit_lower_bound():
    """Explicit list is keyed by absolute position, matching expand-names."""
    array = make_mock_twincatitem(
        name="Main.motors",
        data_type=make_mock_type("MY_STRING", is_string=True),
        pragma="pv: P\naxis-link: GVL.A[10], GVL.A[20], GVL.A[30]",
        array_info=(5, 7),
    )
    chains = list(pragmas.chains_from_symbol(array))
    links = [_get_axis_link(c.last) for c in chains]
    # Outer index 5 → first entry, 6 → second, 7 → third
    assert links == ["GVL.A[10]", "GVL.A[20]", "GVL.A[30]"]


